import type { PaperConfig, PaperId, Problem, QuestionType } from '../types/lecture';

/**
 * EDITABLE SYLLABUS DATA FILE — TGBIE (Telangana Intermediate) Mathematics
 * -------------------------------------------------------------------------
 * 40 Chapters across IA (12), IB (10), IIA (10), IIB (8) × 10 topic-wise
 * practice problems per chapter (400 problems total), organized into 3 TGBIE
 * syllabus topics per chapter covering VSAQ (2M), SAQ (4M), and LAQ (7M).
 */

function makeProblem(
  chapterId: string,
  index: number,
  topic: string,
  type: QuestionType,
  title: string,
  questionLatex: string
): Problem {
  const marksMap: Record<QuestionType, 2 | 4 | 7> = {
    VSAQ: 2,
    SAQ: 4,
    LAQ: 7,
  };
  return {
    id: `${chapterId}-p${index}`,
    chapterId,
    topic,
    type,
    marks: marksMap[type],
    title,
    questionLatex,
    isPractice: true,
    sourceLabel: 'Practice Problem',
  };
}

